{
  "groups": [
    {
      "group_id": "E1",
      "main_query": "当期员工总离职率、主动离职率或其他明确口径离职率及期间 (current employee turnover rate, voluntary turnover rate, reporting period)",
      "supplement_queries": [
        "披露评分年度的员工离职率情况，并能注识别评分期间及离职率口径 (disclose employee turnover rate for the scoring year, identify period and definition)",
        "完成核查未识别当期离职率具体数值 (failed to identify specific current turnover rate value)"
      ]
    },
    {
      "group_id": "E2",
      "main_query": "劳动合同签订、续签、期限、权利义务与合同签订比例 (labor contract signing, renewal, term, rights and obligations, signing ratio)",
      "supplement_queries": [
        "依法与员工签订劳动合同、劳动合同续签、劳动合同期限、劳动合同签订率 (sign labor contracts in accordance with law, renewal, term, signing rate)",
        "未识别员工劳动合同保障的对应内容 (no corresponding content on labor contract protection identified)"
      ]
    },
    {
      "group_id": "E3",
      "main_query": "解雇、裁员、解除劳动关系的通知、协商、补偿、离职争议处理及辞退福利 (dismissal, layoff, termination notice, negotiation, compensation, dispute resolution, severance benefits)",
      "supplement_queries": [
        "辞退福利或成本等可核验的当期补偿事实也可作为本组依据，并注明实际主体与范围 (verifiable current compensation facts such as severance benefits or costs can serve as basis, noting entity and scope)",
        "未识别裁员、解雇相关制度、制度或事实 (no relevant systems or facts on layoffs/dismissals identified)"
      ]
    },
    {
      "group_id": "E4",
      "main_query": "内部招聘、竞聘、内部岗位填补、转岗、岗位轮换、再就业、职业转换培训、退休过渡与返聘 (internal recruitment, competition, internal filling, transfer, rotation, re-employment, career transition training, retirement transition, rehiring)",
      "supplement_queries": [
        "员工内部招聘、内部竞聘、转岗或岗位轮换的制度；内部招聘人数、内部填补岗位比例、轮岗人数等事实 (systems for internal recruitment/competition/transfer/rotation; facts like number of internal hires, fill rate, rotation count)",
        "再就业服务、职业转换培训、退休过渡或返聘的具体支持 (specific support for re-employment services, career transition training, retirement transition, or rehiring)"
      ]
    },
    {
      "group_id": "E5",
      "main_query": "当期辞退福利、终止补偿支付、离职安置受益或相关有效纠正结果 (current severance benefits, termination compensation payment, resettlement benefits, effective corrective results)",
      "supplement_queries": [
        "披露评分年度已经发生的终止补偿支付、就业安置、离职保障受益或相应有效纠正结果至少一项 (disclose at least one actual occurrence in scoring year: termination compensation, job placement, benefit receipt, or effective correction)",
        "没有实际纠正结果，只有政策、计划或承诺 (no actual corrective result, only policies, plans, or commitments)"
      ]
    },
    {
      "group_id": "P1",
      "main_query": "具体工资支付保障政策或事实，如按时足额支付、支付周期或最低工资保障 (specific wage payment guarantee policies or facts, e.g., timely full payment, payment cycle, minimum wage guarantee)",
      "supplement_queries": [
        "依法定周期按时足额支付、最低工资保障，或能识别具体支付内容的执行事实 (pay on time and in full according to legal cycle, minimum wage guarantee, or identifiable execution facts of specific payments)",
        "未识别具体支付保障内容，只有薪酬竞争力或一般激励描述 (no specific payment guarantee content identified, only competitiveness or general incentive descriptions)"
      ]
    },
    {
      "group_id": "P2",
      "main_query": "工资核算、复核、工资单、工资差错查询、薪酬申诉 (wage calculation, review, payslip, wage error inquiry, salary grievance)",
      "supplement_queries": [
        "工资处理及员工查询至少一项具体机制或处理事实，如工资核算规则、核算复核、向员工发放工资单、员工查询工资差错的途径 (at least one specific mechanism or fact for wage processing and employee inquiry, e.g., rules, review, payslips, error inquiry channels)",
        "与工资支付有关的薪酬申诉渠道及处理安排 (salary grievance channels and handling arrangements related to wage payment)"
      ]
    },
    {
      "group_id": "P3",
      "main_query": "工资支付检查、监测、内部审查，以及人力资源审计或人权尽调的工资支付范围 (wage payment inspection, monitoring, internal review, HR audit or human rights due diligence scope regarding wages)",
      "supplement_queries": [
        "定期检查工资支付情况、在人力资源审计或人权尽调中核查工资支付，或对工资支付问题进行内部监测 (regular checks on wage payment, verification in HR audits/HDD, or internal monitoring of wage issues)",
        "使用审计作为依据时，应能识别审计范围涉及工资支付 (when using audit as evidence, must identify that audit scope covers wage payment)"
      ]
    },
    {
      "group_id": "P4",
      "main_query": "对应工资支付保障的政策适用对象或实际覆盖，如全体员工、特定地区、子公司、员工类别、覆盖人数或比例 (applicable subjects or actual coverage of wage payment guarantees, e.g., all employees, specific regions/subsidiaries/categories, headcount or ratio)",
      "supplement_queries": [
        "明确工资支付保障政策或实际执行适用的员工对象，或披露与该保障直接对应的覆盖人数、比例 (clarify employee subjects for wage payment guarantees or disclose directly corresponding coverage numbers/ratios)",
        "未说明工资支付保障对应的对象或范围，或只披露无直接关联的员工总人数或比例 (no subject/scope specified, or only unrelated total employee counts/ratios disclosed)"
      ]
    },
    {
      "group_id": "P5",
      "main_query": "工资差错、欠薪、扣款、加班费问题的补发、退还、复核或已完成纠正 (back-payment, refund, review, or completed correction for wage errors, unpaid wages, deductions, overtime pay issues)",
      "supplement_queries": [
        "披露工资差错、欠薪、扣款或加班费支付问题的至少一项具体补救机制或已完成纠正事实 (disclose at least one specific remedial mechanism or completed correction for wage errors, arrears, deductions, or overtime issues)",
        "未识别对应机制或纠正事实 (no corresponding mechanism or correction fact identified)"
      ]
    },
    {
      "group_id": "T1",
      "main_query": "具体工作时间、排班、轮班、工时控制 (specific working hours, scheduling, shifts, hour control)",
      "supplement_queries": [
        "每周工作天数与每日工时、轮班安排、特定岗位工时制度等 (weekly work days, daily hours, shift arrangements, specific role hour systems)",
        "无对应披露 (no corresponding disclosure)"
      ]
    },
    {
      "group_id": "T2",
      "main_query": "加班申请、审批、自愿性、时长控制、异常处理 (overtime application, approval, voluntariness, duration control, exception handling)",
      "supplement_queries": [
        "员工加班管理直接对应的至少一项具体政策、程序或事实 (at least one specific policy, procedure, or fact directly corresponding to employee overtime management)",
        "无对应披露，只有支付加班费而没有加班管理内容 (no corresponding disclosure, only overtime pay without management content)"
      ]
    },
    {
      "group_id": "T3",
      "main_query": "员工休息、法定假期、年休假及取得安排 (employee rest, statutory holidays, annual leave, and acquisition arrangements)",
      "supplement_queries": [
        "员工依法享有带薪年假、周休或法定节假日，或披露婚假、产假等具体休假安排 (employees enjoy paid annual leave, weekly rest, or statutory holidays per law, or disclose marriage/maternity leave arrangements)",
        "无对应权利或安排披露 (no corresponding rights or arrangement disclosures)"
      ]
    },
    {
      "group_id": "T4",
      "main_query": "考勤系统、工时记录、排班检查、休假申请、调休管理 (attendance system, hour records, schedule checks, leave applications, compensatory leave management)",
      "supplement_queries": [
        "采用考勤系统、记录工时、检查排班、员工申请休假，或办理调休的管理安排 (use attendance systems, record hours, check schedules, employee leave applications, or manage compensatory leave)",
        "无对应机制或事实，只有泛泛管理表述 (no corresponding mechanisms or facts, only vague management statements)"
      ]
    },
    {
      "group_id": "T5",
      "main_query": "当期实际工时监测、休假使用、执行覆盖或工时休假侵害纠正 (current actual hour monitoring, leave usage, execution coverage, or correction of hour/leave infringements)",
      "supplement_queries": [
        "披露评分年度实际发生的至少一项工时监测、休假使用、执行覆盖或工时休假侵害纠正结果 (disclose at least one actual occurrence in scoring year: hour monitoring, leave usage, coverage, or infringement correction)",
        "无实际执行或结果证据，只有制度、工具名称或未来计划 (no evidence of actual execution or results, only system/tool names or future plans)"
      ]
    },
    {
      "group_id": "W1",
      "main_query": "法定社会保险、公积金、养老、医疗等基本福利 (statutory social insurance, housing fund, pension, medical care, basic welfare)",
      "supplement_queries": [
        "养老、医疗、失业、工伤、生育保险，住房公积金或其他运营地适用的法定保障等 (pension, medical, unemployment, work injury, maternity insurance, housing fund, or other applicable statutory protections)",
        "无对应内容，只有无具体项目的笼统合规声明 (no corresponding content, only vague compliance statements without specific items)"
      ]
    },
    {
      "group_id": "W2",
      "main_query": "补充医疗、商业保险、年金、餐补、交通补助 (supplementary medical, commercial insurance, annuity, meal subsidy, transport allowance)",
      "supplement_queries": [
        "面向员工的至少一项具体补充福利安排或事实 (at least one specific supplementary welfare arrangement or fact for employees)",
        "政策安排和已经发放、投保等事实分别记录 (record policy arrangements and facts like issuance/insurance separately)"
      ]
    },
    {
      "group_id": "W3",
      "main_query": "员工育儿、托育、家庭照护、心理支持、员工援助计划 (childcare, family care, psychological support, Employee Assistance Program/EAP)",
      "supplement_queries": [
        "面向员工的至少一项家庭或生活支持资源、服务或安排 (at least one family or life support resource/service/arrangement for employees)",
        "无对应披露，或内容仅面向社区和客户 (no corresponding disclosure, or content only for community/customers)"
      ]
    },
    {
      "group_id": "W4",
      "main_query": "福利适用对象、申请条件、补贴标准、报销或领取方式 (welfare applicability, eligibility conditions, subsidy standards, reimbursement or collection methods)",
      "supplement_queries": [
        "适用全体在册员工、满足某项申请条件、按规定标准领取补贴，或规定报销及领取方式等 (applies to all registered employees, meets certain conditions, receives subsidies per standards, or specifies reimbursement/collection methods)",
        "无对应取得规则，只有活动名称或口号 (no corresponding acquisition rules, only activity names or slogans)"
      ]
    },
    {
      "group_id": "W5",
      "main_query": "当期参保、投保、缴纳、补贴发放、福利使用或受益案例 (current enrollment, insurance purchase, contribution, subsidy distribution, welfare usage, or beneficiary cases)",
      "supplement_queries": [
        "披露评分年度已经发生的至少一项福利覆盖、使用或受益事实 (disclose at least one actual occurrence in scoring year: welfare coverage, usage, or benefit receipt)",
        "无已发生事实，只有可申请资格、预算或计划 (no occurred facts, only eligibility, budget, or plans)"
      ]
    },
    {
      "group_id": "D1",
      "main_query": "员工反歧视政策、禁止歧视要求或具体保障 (employee anti-discrimination policies, prohibition requirements, or specific safeguards)",
      "supplement_queries": [
        "反对或禁止员工相关歧视的政策要求，或防止就业中不正当差别待遇的具体制度、措施或事实 (policy requirements against/prohibiting discrimination, or specific systems/measures/facts preventing unfair treatment in employment)",
        "完成核查仍无明确对应内容，只有一般多元化倡议或普通招聘晋升管理描述 (no clear corresponding content after verification, only general diversity initiatives or ordinary recruitment/promotion descriptions)"
      ]
    },
    {
      "group_id": "D2",
      "main_query": "反骚扰、反性骚扰、职场骚扰零容忍或具体防护 (anti-harassment, anti-sexual harassment, zero tolerance for workplace harassment, or specific protections)",
      "supplement_queries": [
        "禁止职场骚扰、反性骚扰或相应零容忍要求，或保护员工免受骚扰的具体制度、措施或事实 (prohibition of workplace/sexual harassment, zero tolerance, or specific systems/measures/facts protecting employees from harassment)",
        "完成核查仍无明确对应内容，只有反腐或一般商业道德表述 (no clear corresponding content after verification, only anti-corruption or general business ethics statements)"
      ]
    },
    {
      "group_id": "D3",
      "main_query": "适用于歧视骚扰投诉的受理、调查、核查或处理 (acceptance, investigation, verification, or handling applicable to discrimination/harassment complaints)",
      "supplement_queries": [
        "明确专门机构接收并调查此类投诉，或披露当期针对歧视骚扰投诉已开展的调查 (specify dedicated agency receiving/investigating such complaints, or disclose current investigations conducted)",
        "未识别对应机制或事实，只有未说明适用本议题的联系方式 (no corresponding mechanism or fact identified, only contact info not specifying applicability to this topic)"
      ]
    },
    {
      "group_id": "D4",
      "main_query": "适用于歧视骚扰投诉的保密、匿名、不报复、隔离或支持 (confidentiality, anonymity, non-retaliation, isolation, or support applicable to discrimination/harassment complaints)",
      "supplement_queries": [
        "对投诉人及投诉内容保密、匿名举报、不报复、风险隔离或支持措施等 (confidentiality of complainant/content, anonymous reporting, non-retaliation, risk isolation, or support measures)",
        "未识别对应保护安排或事实 (no corresponding protection arrangements or facts identified)"
      ]
    },
    {
      "group_id": "D5",
      "main_query": "歧视骚扰的处分、问责、移交及具体纠正补救 (disciplinary action, accountability, referral, and specific corrective remedies for discrimination/harassment)",
      "supplement_queries": [
        "针对查实歧视或骚扰的处分、问责或移交处理规则，或具体补救机制、实际处置事实 (rules for discipline/accountability/referral upon verified discrimination/harassment, or specific remedial mechanisms/actual disposal facts)",
        "未识别对应规则、机制或事实，只有无实质内容的“持续改进” (no corresponding rules/mechanisms/facts identified, only substantive-less \"continuous improvement\")"
      ]
    }
  ]
}
